"""Read the private configuration generated by init_env.py without using a shell."""

import os
import re
import shlex
import stat
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parents[2]
PUBLIC_ROOT = Path("/home/amelone/www")
MAX_SIZE = 64 * 1024
ERROR_MESSAGE = "La configuration privée AMELONE est inaccessible ou invalide."
ALLOWED_KEYS = frozenset({
    "DJANGO_SETTINGS_MODULE", "DJANGO_DEBUG", "ALWAYSDATA_SITE_HOST",
    "DJANGO_SECRET_KEY", "DATABASE_URL", "ALWAYSDATA_HSTS_SECONDS",
    "ALWAYSDATA_ENABLE_EMAILS", "EMAIL_ENABLED", "EVENT_NOTIFICATIONS_ENABLED",
    "EMAIL_PROVIDER", "DEFAULT_FROM_EMAIL", "BREVO_API_KEY", "SMS_ENABLED",
})


def _read_values(path):
    if not path.is_absolute():
        raise ValueError
    resolved = path.resolve(strict=True)
    for root in (PROJECT_ROOT, PUBLIC_ROOT):
        if path.is_relative_to(root) or resolved.is_relative_to(root):
            raise ValueError
    before = path.lstat()
    if not stat.S_ISREG(before.st_mode):
        raise ValueError
    descriptor = os.open(path, os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0) | os.O_NONBLOCK)
    with os.fdopen(descriptor, "rb") as source:
        metadata = os.fstat(source.fileno())
        if (
            not stat.S_ISREG(metadata.st_mode)
            or (metadata.st_dev, metadata.st_ino) != (before.st_dev, before.st_ino)
            or metadata.st_uid != os.geteuid()
            or metadata.st_mode & 0o077
            or metadata.st_size > MAX_SIZE
        ):
            raise ValueError
        raw = source.read(MAX_SIZE + 1)
    if len(raw) > MAX_SIZE:
        raise ValueError
    values = {}
    for line in raw.decode("utf-8").splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        match = re.fullmatch(r"export[ \t]+([A-Z_][A-Z0-9_]*)=(.*)", line)
        if not match:
            raise ValueError
        key, literal = match.groups()
        if key not in ALLOWED_KEYS or key in values:
            raise ValueError
        tokens = shlex.split(line, comments=False, posix=True)
        if len(tokens) != 2 or tokens[0] != "export" or not tokens[1].startswith(f"{key}="):
            raise ValueError
        value = tokens[1].split("=", 1)[1]
        # Accept generator output and simple single-quoted manual values.
        # Unquoted shell substitutions and commands remain rejected.
        if "\x00" in value or (
            literal != shlex.quote(value) and re.fullmatch(r"'[^']*'", literal) is None
        ):
            raise ValueError
        values[key] = value
    return values


def load_private_environment(path=None):
    """Load an optional private file atomically; file values override inherited ones."""
    if path is None:
        path = os.environ.get("ALWAYSDATA_ENV_FILE")
    if path is None:
        return
    try:
        values = _read_values(Path(path))
    except (OSError, ValueError, UnicodeError, RuntimeError):
        raise ValueError(ERROR_MESSAGE) from None
    os.environ.update(values)
